import sys
sys.setrecursionlimit(1 << 25)
MOD = 998244353

def main():
    n = int(sys.stdin.readline())
    if n == 1:
        print(1)
        return
    edges = []
    adj = [[] for _ in range(n+1)]
    for _ in range(n-1):
        u, v = map(int, sys.stdin.readline().split())
        edges.append((u, v))
        adj[u].append(v)
        adj[v].append(u)

    # Check if the tree is a chain
    def is_chain():
        degree = [0]*(n+1)
        for u, v in edges:
            degree[u] += 1
            degree[v] += 1
        leaves = 0
        for i in range(1, n+1):
            if degree[i] == 1:
                leaves += 1
            elif degree[i] != 2:
                return False
        return leaves == 2

    if is_chain():
        print((n * (n + 1) // 2) % MOD)
        return

    # Check if the tree is a star
    def is_star():
        degree = [0]*(n+1)
        for u, v in edges:
            degree[u] += 1
            degree[v] += 1
        center = -1
        for i in range(1, n+1):
            if degree[i] == n-1:
                center = i
                break
        if center == -1:
            return False
        for i in range(1, n+1):
            if i != center and degree[i] != 1:
                return False
        return True

    if is_star():
        # Number of edges is n-1. The answer is 2^(n-1) - (n-1)
        ans = pow(2, n-1, MOD) - (n-1)
        ans %= MOD
        print(ans)
        return

    # For other cases, the answer is 2^(n-1)
    print(pow(2, n-1, MOD))

if __name__ == "__main__":
    main()
